import pandas as pd
import numpy as np
from sklearn.linear_model import LinearRegression, RidgeCV, ElasticNetCV
from sklearn.model_selection import KFold, cross_val_predict
from sklearn.metrics import r2_score, mean_absolute_error
from sklearn.preprocessing import StandardScaler
import warnings
warnings.filterwarnings('ignore')

train = pd.read_csv('alloy_pair_max_train.csv')
pool = pd.read_csv('alloy_pair_max_pool.csv')
y = train['target'].values

els = ['C','Mn','Si','Cr','Ni','Mo','V','Nb','Co','Al','Ti','Cu','Fe']
proc = ['solutionizing_temp','aging_temp','aging_time','cooling_rate']
hts = ['annealed','quenched','quench_temper','solution_aged']
rts = ['cast','AM','wrought']

def feats(df, mode='sq'):
    X = df[els+proc].copy()
    for ht in hts:
        X[f'ht_{ht}'] = (df['heat_treatment']==ht).astype(float)
    for rt in rts:
        X[f'rt_{rt}'] = (df['route']==rt).astype(float)
    if 'sq' in mode:
        for e in els:
            X[f'{e}2'] = df[e]**2
    if 'proc2' in mode:
        for p in proc:
            X[f'{p}2'] = df[p]**2
        X['ageT_time'] = df['aging_temp']*df['aging_time']
    if 'htxrt' in mode:
        for ht in hts:
            for rt in rts:
                X[f'{ht}_{rt}'] = ((df['heat_treatment']==ht)&(df['route']==rt)).astype(float)
    if 'htxproc' in mode:
        for ht in hts:
            m = (df['heat_treatment']==ht).astype(float)
            for p in proc:
                X[f'{ht}_{p}'] = m*df[p]
    if 'htxel' in mode:
        for ht in hts:
            m = (df['heat_treatment']==ht).astype(float)
            for e in ['C','Al','V','Mo','Cu','Mn','Nb']:
                X[f'{e}_{ht}'] = m*df[e]
    if 'pair' in mode:
        for i,a in enumerate(els):
            for b in els[i+1:]:
                X[f'{a}_{b}'] = df[a]*df[b]
    return X

kf = KFold(10, shuffle=True, random_state=0)

modes = ['sq', 'sq+proc2', 'sq+htxrt', 'sq+htxproc', 'sq+htxel', 'sq+htxrt+htxproc',
         'sq+htxrt+htxproc+htxel', 'sq+pair', 'sq+proc2+htxrt']

for mode in modes:
    X = feats(train, mode)
    # Linear
    oof = cross_val_predict(LinearRegression(), X, y, cv=kf)
    print(f'OLS {mode:30s} n={X.shape[1]:3d} R2={r2_score(y,oof):.4f} MAE={mean_absolute_error(y,oof):.2f}')
    # Ridge
    Xs = StandardScaler().fit_transform(X)
    oof = cross_val_predict(RidgeCV(alphas=np.logspace(-2,3,20)), Xs, y, cv=kf)
    print(f'Ridge {mode:28s} n={X.shape[1]:3d} R2={r2_score(y,oof):.4f} MAE={mean_absolute_error(y,oof):.2f}')
